import { test } from 'node:test'
import assert from 'node:assert/strict'
import { createServer } from 'node:http'
import { createApp } from '../src/app.mjs'

const prices = { A: 10, B: 25.5, C: 0.1, D: 33.33 }
const pricing = { priceOf: async (sku) => prices[sku] }

async function totalFor(items) {
  const server = createServer(createApp({ pricing }))
  await new Promise((r) => server.listen(0, r))
  try {
    const res = await fetch(`http://localhost:${server.address().port}/orders`, {
      method: 'POST', body: JSON.stringify({ items }),
    })
    assert.equal(res.status, 201)
    const order = await res.json()
    const got = await (await fetch(`http://localhost:${server.address().port}/orders/${order.id}`)).json()
    assert.equal(got.total, order.total)
    return order.total
  } finally { server.close() }
}

// Characterization tests: they pin current behaviour, including the questionable parts.
test('single and multiple items are summed as price * qty', async () => {
  assert.equal(await totalFor([{ sku: 'A', qty: 3 }]), 30)
  assert.equal(await totalFor([{ sku: 'A', qty: 2 }, { sku: 'B', qty: 2 }]), 71)
})

test('no discount at exactly 100 (threshold is exclusive)', async () => {
  assert.equal(await totalFor([{ sku: 'A', qty: 10 }]), 100)
})

test('10% discount just above threshold: 100.5 -> 90.45 -> floor 90', async () => {
  assert.equal(await totalFor([{ sku: 'C', qty: 1005 }]), 90)
})

test('10% discount on larger orders', async () => {
  assert.equal(await totalFor([{ sku: 'A', qty: 11 }]), 99)
  assert.equal(await totalFor([{ sku: 'A', qty: 50 }]), 450)
  assert.equal(await totalFor([{ sku: 'A', qty: 1000 }]), 9000)
})

test('total is floored to whole euros, dropping cents (no rounding)', async () => {
  assert.equal(await totalFor([{ sku: 'D', qty: 1 }]), 33)
  assert.equal(await totalFor([{ sku: 'D', qty: 7 }]), 209) // 233.31 * 0.9 = 209.979
})

test('discount applies to the whole order, so crossing 100 lowers the total', async () => {
  const below = await totalFor([{ sku: 'A', qty: 10 }])
  const above = await totalFor([{ sku: 'A', qty: 11 }])
  assert.ok(above < 110 && above === 99 && below === 100)
})
EOF
